def max_Abs_Diff(arr, n):
    """Write a python function to find the maximum difference between any two elements in a given array."""
    if arr is None:
        return 0
    elements = list(arr)
    if n is not None:
        if n <= 0:
            return 0
        elements = elements[:n]
    if len(elements) < 2:
        return 0
    return abs(max(elements) - min(elements))
